import type { OntologyApiDocsData } from "@/types";

/**
 * @description 判断未知值是否为可展示的本体 OpenAPI 文档结构。
 * @param value 待校验值。
 * @returns 是否满足最小 OpenAPI 文档字段。
 */
function isOntologyApiDocsData(value: unknown): value is OntologyApiDocsData {
  if (value === null || typeof value !== "object") {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  if (
    typeof candidate.openapi !== "string" ||
    typeof candidate.info !== "object" ||
    candidate.info === null ||
    typeof candidate.paths !== "object" ||
    candidate.paths === null
  ) {
    return false;
  }
  const info = candidate.info as Record<string, unknown>;
  return typeof info.title === "string" && typeof info.version === "string";
}

/**
 * @description 解析用户提供的 OpenAPI 3.1 样例文档。
 * @param rawJson OpenAPI JSON 文本。
 * @returns 类型化的本体接口文档数据。
 */
function parseApiDocsOntologyMock(rawJson: string): OntologyApiDocsData {
  const parsed: unknown = JSON.parse(rawJson);
  if (!isOntologyApiDocsData(parsed)) {
    throw new Error("apiDocsOntologyMock 不是有效的 OpenAPI 文档结构。");
  }
  return parsed;
}

